class TicketValidator:
    def __init__(self, schema):
        self._schema = schema

    def validate(self, data):
        errors = {}
        cleaned = {}
        for rule in self._schema:
            field = rule['field']
            type_name = rule.get('type', 'str')
            value = data.get(field)
            if value is None:
                if rule.get('required'):
                    errors[field] = 'required'
                else:
                    cleaned[field] = rule.get('default')
            else:
                try:
                    if type_name == 'int':
                        cleaned[field] = int(value)
                    elif type_name == 'bool':
                        if not isinstance(value, bool):
                            raise ValueError()
                        cleaned[field] = value
                    else:
                        cleaned[field] = str(value).strip()
                except (ValueError, TypeError):
                    errors[field] = f'expected {type_name}'
        if errors:
            return [False, errors]
        return [True, cleaned]

    def describe(self):
        return {rule['field']: rule.get('type', 'str') for rule in self._schema}
